import { dirname } from 'node:path';
import { planStack, resolveStackIdByNameOrId } from '../../actions/blueprints/stacks.js';
import { extractDurableConfig } from '../../utils/blueprints/extract-durable-config.js';
import { createHintCollector } from '../../utils/blueprints/hints.js';
import { stampInstallationConfigVersion } from '../../utils/blueprints/stamp-installation-config-version.js';
import { formatDeploymentPlan, formatResourceTree, hasActionableChanges, } from '../../utils/display/blueprints-formatting.js';
import { runCommand } from '../../utils/package-manager.js';
import { styleText } from '../../utils/style-text.js';
import { getWarnings } from '../../utils/warnings.js';
export async function blueprintPlanCore(options) {
    const { bin = 'sanity', log, blueprint, token, flags } = options;
    const { verbose: _verbose = false } = flags;
    const { scopeType, scopeId, stackId: blueprintStackId, parsedBlueprint, resources, fileInfo, } = blueprint;
    log(`${styleText(['bold', 'blueBright'], 'Local Blueprint')} ${styleText('dim', `(${fileInfo.fileName})`)}`);
    await extractDurableConfig(resources, dirname(fileInfo.blueprintFilePath));
    await stampInstallationConfigVersion(resources, dirname(fileInfo.blueprintFilePath));
    log(formatResourceTree(resources));
    if (!token || !scopeType || !scopeId) {
        log(styleText('dim', 'Unable to retrieve live Stack deployment for comparison'));
        return !token
            ? {
                success: false,
                error: 'Missing authentication token',
                suggestions: [`Run \`${runCommand(bin)} login\` to authenticate.`],
            }
            : {
                success: false,
                error: 'Missing Blueprint configuration',
                suggestions: [
                    `Run \`${runCommand(bin)} blueprints doctor --fix\` to fix your configuration.`,
                ],
            };
    }
    const stackId = flags.stack
        ? await resolveStackIdByNameOrId(flags.stack, { token, scopeType, scopeId }, log)
        : blueprintStackId;
    if (!stackId) {
        log(styleText('dim', 'Unable to retrieve live Stack deployment for comparison'));
        return {
            success: false,
            error: 'Missing Stack deployment configuration',
            suggestions: [
                `Run \`${runCommand(bin)} blueprints doctor --fix\` to fix your configuration.`,
            ],
        };
    }
    const auth = { token, scopeType, scopeId };
    const spinner = log.ora('Generating deployment plan...').start();
    const planResponse = await planStack({
        stackId,
        document: parsedBlueprint,
        auth,
        logger: log,
    });
    spinner.stop().clear();
    if (!planResponse.ok) {
        const hints = createHintCollector(bin);
        if (planResponse.problems) {
            log('');
            for (const problem of planResponse.problems) {
                hints.inspectMessage(problem.message);
                const messages = problem.message
                    .split('\n')
                    .map((s) => s.trim())
                    .filter(Boolean);
                for (const msg of messages) {
                    log(`  ${styleText(['bold', 'red'], '✘')} ${msg}`);
                }
            }
        }
        else {
            log(styleText('dim', '\nUnable to retrieve deployment plan from server'));
        }
        return {
            success: false,
            error: 'Deployment plan has problems',
            suggestions: [
                ...hints.getSuggestions(),
                `Fix the issues above, then run \`${runCommand(bin)} blueprints plan\` again.`,
            ],
        };
    }
    const warnings = getWarnings({ dir: dirname(fileInfo.blueprintFilePath) });
    log('');
    log(formatDeploymentPlan(planResponse.deploymentPlan));
    if (hasActionableChanges(planResponse.deploymentPlan)) {
        log(`\n  Run "${styleText(['bold', 'magenta'], `${runCommand(bin)} blueprints deploy`)}" to apply these Stack changes`);
    }
    else {
        log(`\n  ${styleText('dim', `No significant changes to deploy. Run \`${runCommand(bin)} blueprints deploy\` to apply.`)}`);
    }
    return {
        success: true,
        json: {
            resources,
            plan: planResponse.deploymentPlan,
        },
        warnings: warnings,
    };
}
